export function cultureFigure({medium='agar',inverted=false,tape='none',media='uncertain',loop='uncertain',temperature=25}={}){return `<svg class="shell-diagram" viewBox="0 0 480 330" role="img" aria-label="${medium==='broth'?'Nutrient broth bottle':'Nutrient agar plate'}; ${inverted?'inverted':'upright'}; lid ${tape}; media ${media}; loop ${loop}; school temperature choice ${temperature} degrees Celsius.">${medium==='broth'?'<path d="M175 55H305V85Q335 110 335 140V270H145V140Q145 110 175 85Z" fill="#b7c8d6" fill-opacity=".18" stroke="#f8f6f2" stroke-width="3"/><path d="M149 170H331V266H149Z" fill="#ed8b78" fill-opacity=".35"/><path d="M175 50H305" stroke="#d4dfe7" stroke-width="15"/>':'<ellipse cx="240" cy="175" rx="175" ry="75" fill="#b7c8d6" fill-opacity=".12" stroke="#d4dfe7" stroke-width="3"/><ellipse cx="240" cy="175" rx="160" ry="60" fill="#ed8b78" fill-opacity=".3"/>'+Array.from({length:9},(_,i)=>`<ellipse cx="${140+(i%3)*85}" cy="${145+Math.floor(i/3)*28}" rx="8" ry="4" fill="#f8f6f2"/>`).join('')+`<path d="M65 ${inverted?155:125}Q240 ${inverted?45:15} 415 ${inverted?155:125}" fill="none" stroke="#f8f6f2" stroke-width="4"/>${tape==='strips'?'<path d="M102 101L118 140M365 101L352 140" stroke="#b7c8d6" stroke-width="12"/>':tape==='sealed'?'<ellipse cx="240" cy="125" rx="175" ry="60" fill="none" stroke="#b7c8d6" stroke-width="12"/>':''}`}<text x="240" y="305" text-anchor="middle" fill="#f8f6f2" font-size="13">${medium==='broth'?'Cells suspended in nutrient broth':inverted?'Inverted: condensation kept off agar':'Agar surface supports visible colonies'}</text></svg>`;}
export function growthFigure({initial=2,step=0,division=20,supported=true}={}){const count=initial*2**step,shown=Math.min(count,64);return `<svg class="shell-diagram" viewBox="0 0 480 330" role="img" aria-label="${supported?count+' bacteria after '+step+' complete divisions':'Constant doubling prediction is unsupported by these conditions'}; ideal population model"><rect x="30" y="45" width="420" height="215" rx="25" fill="#b7c8d6" fill-opacity=".08" stroke="#b7c8d6"/>${supported?Array.from({length:shown},(_,i)=>`<rect x="${55+(i%8)*48}" y="${65+Math.floor(i/8)*24}" width="23" height="11" rx="6" fill="#ed8b78" stroke="#f8f6f2"/>`).join(''):'<text x="240" y="155" text-anchor="middle" fill="#f8f6f2" font-size="32">?</text>'}<text x="240" y="25" text-anchor="middle" fill="#f8f6f2" font-size="16">${supported?'Population: '+count:'Growth cannot be predicted from this model'}</text><text x="240" y="290" text-anchor="middle" fill="#f8f6f2" font-size="13">${supported?step+' complete divisions · '+step*division+' supplied minutes':'Supplied doubling assumptions not met'}</text><text x="240" y="318" text-anchor="middle" fill="#b7c8d6" font-size="12">${supported?(count>64?'64 symbols shown; use the labelled total':'One symbol per model cell')+' · no deaths assumed':'No exact population predicted'}</text></svg>`;}
export function zoneFigure({diameter=20,disc=6,axis=0,start=0,end=0,assessment=false,otherDiameter=diameter}={}){const ink=assessment?'#182e44':'#f8f6f2',soft=assessment?'#526f86':'#b7c8d6',scale=6,r=Math.min(110,Number(diameter)*scale/2),dr=Number(disc)*scale/2,ry=Math.min(110,Number(otherDiameter)*scale/2);return `<svg class="shell-diagram" viewBox="0 0 480 350" role="img" aria-label="Model inhibition plate; clear-zone diameter ${diameter} millimetres, disc diameter ${disc} millimetres. ${assessment?'':axis===90?'Ruler on second axis.':'Ruler on first axis.'}"><circle cx="240" cy="155" r="125" fill="${soft}" fill-opacity=".15" stroke="${soft}" stroke-width="3"/>${Array.from({length:65},(_,i)=>{const a=i*2.4,rad=65+((i*17)%55),x=240+Math.cos(a)*rad,y=155+Math.sin(a)*rad;return Math.hypot(x-240,y-155)>r+5?`<circle cx="${x}" cy="${y}" r="2.5" fill="#ed8b78"/>`:'';}).join('')}<ellipse cx="240" cy="155" rx="${r}" ry="${ry}" fill="${assessment?'#fff':'#182e44'}" stroke="${ink}"/><circle cx="240" cy="155" r="${dr}" fill="#ed8b78" stroke="${ink}"/>${assessment?`<path d="M${240-r} 155H${240+r}" stroke="${ink}"/><text x="240" y="315" text-anchor="middle" fill="${ink}" font-size="14">Clear-zone diameter ${diameter} mm · disc ${disc} mm</text>`:`<g transform="rotate(${axis} 240 155)"><path d="M120 155H360" stroke="${ink}" stroke-width="2"/>${Array.from({length:9},(_,i)=>`<path d="M${120+i*30} 147V163" stroke="${ink}"/><text x="${120+i*30}" y="182" text-anchor="middle" fill="${ink}" font-size="10">${i*5}</text>`).join('')}<path d="M${120+Number(start)*6} 132V193M${120+Number(end)*6} 132V193" stroke="#ed8b78" stroke-width="3"/></g><text x="240" y="315" text-anchor="middle" fill="${ink}" font-size="13">Ruler units: mm · centre at20 mm</text><text x="240" y="340" text-anchor="middle" fill="${soft}" font-size="12">Clear zone includes central disc unless asked otherwise</text>`}</svg>`;}
